html = f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>John's 40th — Find Your Perfect Trip</title>
<style>
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Inter:wght@300;400;500;600;700&display=swap');
:root{{--gold:#f0c040;--white:#fff;--dim:rgba(255,255,255,0.55);--dimmer:rgba(255,255,255,0.25);--bg:#08080f;--card:rgba(255,255,255,0.05);--cb:rgba(255,255,255,0.1);--r:20px;}}
*{{margin:0;padding:0;box-sizing:border-box;}}
body{{font-family:'Inter',sans-serif;background:var(--bg);color:var(--white);min-height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:20px;overflow-x:hidden;}}
body::before{{content:'';position:fixed;inset:0;background:radial-gradient(ellipse 80% 50% at 20% 20%,rgba(120,60,200,.12) 0%,transparent 60%),radial-gradient(ellipse 60% 40% at 80% 80%,rgba(240,150,40,.1) 0%,transparent 60%);pointer-events:none;z-index:0;}}
.container{{width:100%;max-width:860px;position:relative;z-index:1;}}
.screen{{display:none;}}.screen.active{{display:block;animation:fi .35s ease;}}
@keyframes fi{{from{{opacity:0;transform:translateY(10px)}}to{{opacity:1;transform:translateY(0)}}}}

/* INTRO */
.intro-tag{{font-size:11px;letter-spacing:4px;text-transform:uppercase;color:var(--gold);text-align:center;margin-bottom:16px;}}
.intro-title{{font-family:'Playfair Display',serif;font-size:clamp(36px,6vw,62px);font-weight:900;text-align:center;line-height:1.05;margin-bottom:16px;background:linear-gradient(135deg,#fff 0%,#f0c040 60%,#ff8c42 100%);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;}}
.intro-sub{{font-size:clamp(14px,1.8vw,17px);color:var(--dim);text-align:center;line-height:1.7;max-width:520px;margin:0 auto 36px;font-weight:300;}}
.name-section{{background:var(--card);border:1px solid var(--cb);border-radius:var(--r);padding:28px 24px;margin-bottom:28px;}}
.name-section-label{{font-size:12px;letter-spacing:2px;text-transform:uppercase;color:var(--dim);margin-bottom:18px;display:block;text-align:center;}}
.name-choices{{display:flex;gap:16px;justify-content:center;flex-wrap:wrap;}}
.name-choice{{flex:1;min-width:160px;max-width:200px;background:var(--card);border:2px solid var(--cb);border-radius:18px;padding:0;cursor:pointer;font-family:'Inter',sans-serif;transition:all .2s;overflow:hidden;display:flex;flex-direction:column;align-items:center;}}
.name-photo{{width:100%;aspect-ratio:3/4;object-fit:cover;object-position:top center;display:block;transition:transform .3s;}}
.name-choice:hover .name-photo{{transform:scale(1.03);}}
.name-label-text{{display:block;padding:12px 8px;font-size:15px;font-weight:700;color:var(--dim);}}
.name-choice:hover{{border-color:rgba(240,192,64,.5);}}.name-choice:hover .name-label-text{{color:white;}}
.name-choice.selected{{border-color:var(--gold);box-shadow:0 0 0 3px rgba(240,192,64,.2);}}.name-choice.selected .name-label-text{{color:var(--gold);}}
.dest-preview{{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;margin-bottom:32px;}}
.dest-chip-i{{background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.1);border-radius:24px;padding:5px 13px;font-size:12px;color:var(--dim);}}
.btn-primary{{display:block;width:100%;background:linear-gradient(135deg,#f0c040,#ff8c42);border:none;border-radius:14px;padding:18px;font-size:17px;font-weight:700;color:#1a0a00;cursor:pointer;transition:transform .15s,box-shadow .15s;}}
.btn-primary:hover{{transform:translateY(-2px);box-shadow:0 8px 30px rgba(240,192,64,.3);}}.btn-primary:disabled{{opacity:.4;cursor:default;transform:none;box-shadow:none;}}

/* QUESTION HEADER */
.pb-wrap{{height:3px;background:rgba(255,255,255,.1);border-radius:2px;margin-bottom:28px;overflow:hidden;}}
.pb-fill{{height:100%;background:linear-gradient(to right,#f0c040,#ff8c42);border-radius:2px;transition:width .4s ease;}}
.q-meta{{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;flex-wrap:wrap;gap:8px;}}
.q-num{{font-size:11px;letter-spacing:3px;text-transform:uppercase;color:var(--gold);}}
.q-rm{{display:flex;gap:10px;align-items:center;}}
.q-badge{{font-size:10px;background:rgba(240,192,64,.15);color:var(--gold);border:1px solid rgba(240,192,64,.3);border-radius:20px;padding:3px 10px;letter-spacing:1px;text-transform:uppercase;}}
.q-cnt{{font-size:12px;color:var(--dimmer);}}
.q-text{{font-family:'Playfair Display',serif;font-size:clamp(20px,3vw,30px);font-weight:700;line-height:1.25;margin-bottom:8px;}}
.q-hint{{font-size:12px;color:var(--dimmer);margin-bottom:18px;font-style:italic;}}

/* HERO IMAGE (one per question) */
.hero-img-wrap{{width:100%;height:220px;border-radius:16px;overflow:hidden;margin-bottom:20px;background:rgba(255,255,255,.04);}}
.hero-img{{width:100%;height:100%;object-fit:cover;display:block;}}

/* PHOTO CARDS (Q3, Q4, Q7) */
.options-grid{{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:14px;}}
.option-card{{background:var(--card);border:2px solid var(--cb);border-radius:16px;cursor:pointer;overflow:hidden;transition:all .2s;text-align:left;color:white;font-family:'Inter',sans-serif;display:flex;flex-direction:column;}}
.option-card:hover{{border-color:rgba(240,192,64,.45);transform:translateY(-2px);box-shadow:0 6px 20px rgba(0,0,0,.3);}}
.option-card.selected{{border-color:var(--gold);background:rgba(240,192,64,.08);}}
.option-img-wrap{{position:relative;width:100%;height:155px;overflow:hidden;background:rgba(255,255,255,.04);}}
.option-img{{width:100%;height:155px;object-fit:cover;display:block;transition:transform .3s;}}
.option-card:hover .option-img{{transform:scale(1.04);}}
.option-body{{padding:12px 14px 14px;flex:1;display:flex;flex-direction:column;gap:4px;}}
.opt-top{{display:flex;align-items:flex-start;justify-content:space-between;gap:8px;}}
.opt-em{{font-size:18px;flex-shrink:0;margin-top:1px;}}
.opt-chk{{width:20px;height:20px;border:2px solid rgba(255,255,255,.2);border-radius:50%;flex-shrink:0;display:flex;align-items:center;justify-content:center;transition:all .2s;font-size:11px;margin-top:1px;}}
.opt-chk.cb{{border-radius:5px;}}.option-card.selected .opt-chk{{background:var(--gold);border-color:var(--gold);color:#1a0a00;}}
.opt-lbl{{font-size:13px;font-weight:700;line-height:1.3;flex:1;}}
.opt-sub{{font-size:11px;color:var(--dim);line-height:1.4;margin-top:2px;}}

/* BUTTON OPTIONS (heroImg questions, slideshow questions, btnOnly) */
.options-btn-grid{{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:12px;}}
.option-btn{{background:var(--card);border:2px solid var(--cb);border-radius:16px;padding:16px;cursor:pointer;color:white;font-family:'Inter',sans-serif;text-align:left;transition:all .2s;display:flex;align-items:flex-start;gap:12px;}}
.option-btn:hover{{border-color:rgba(240,192,64,.45);transform:translateY(-2px);box-shadow:0 6px 20px rgba(0,0,0,.25);}}
.option-btn.selected{{border-color:var(--gold);background:rgba(240,192,64,.08);}}
.opt-btn-icon{{font-size:24px;flex-shrink:0;margin-top:1px;}}
.opt-btn-content{{flex:1;}}
.opt-btn-lbl{{font-size:13px;font-weight:700;line-height:1.3;display:block;margin-bottom:3px;}}
.opt-btn-sub{{font-size:11px;color:var(--dim);line-height:1.4;display:block;}}
.opt-btn-chk{{width:20px;height:20px;border:2px solid rgba(255,255,255,.2);border-radius:50%;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:11px;margin-top:2px;transition:all .2s;}}
.opt-btn-chk.cb{{border-radius:5px;}}.option-btn.selected .opt-btn-chk{{background:var(--gold);border-color:var(--gold);color:#1a0a00;}}

/* CHIPS */
.chips-grid{{display:flex;flex-wrap:wrap;gap:12px;}}
.chip-opt{{display:flex;align-items:center;gap:8px;background:var(--card);border:2px solid var(--cb);border-radius:40px;padding:10px 18px;cursor:pointer;font-family:'Inter',sans-serif;color:white;font-size:14px;font-weight:600;transition:all .2s;}}
.chip-opt:hover{{border-color:rgba(240,192,64,.5);}}.chip-opt.selected{{border-color:var(--gold);background:rgba(240,192,64,.1);color:var(--gold);}}

/* NAV */
.nav-row{{display:flex;gap:12px;margin-top:24px;}}
.btn-back{{flex:0 0 auto;background:none;border:1px solid var(--cb);border-radius:14px;padding:15px 20px;font-size:15px;font-weight:600;color:var(--dimmer);cursor:pointer;font-family:'Inter',sans-serif;transition:all .2s;}}
.btn-back:hover{{border-color:rgba(255,255,255,.25);color:white;}}.btn-back:disabled{{opacity:.2;cursor:default;}}
.btn-next{{flex:1;background:var(--gold);border:none;border-radius:14px;padding:16px;font-size:16px;font-weight:700;color:#1a0a00;cursor:pointer;transition:all .2s;opacity:0;pointer-events:none;transform:translateY(8px);font-family:'Inter',sans-serif;}}
.btn-next.visible{{opacity:1;pointer-events:all;transform:translateY(0);}}.btn-next:hover{{box-shadow:0 6px 24px rgba(240,192,64,.3);}}
.btn-skip{{display:block;text-align:center;font-size:13px;color:var(--dimmer);background:none;border:none;cursor:pointer;font-family:'Inter',sans-serif;margin-top:10px;padding:6px;transition:color .2s;}}
.btn-skip:hover{{color:white;}}

/* SEALED */
.sealed-screen{{text-align:center;padding:40px 20px;}}
.sealed-icon{{font-size:80px;margin-bottom:24px;display:block;animation:bounce 1s ease infinite alternate;}}
@keyframes bounce{{from{{transform:translateY(0)}}to{{transform:translateY(-12px)}}}}
.sealed-title{{font-family:'Playfair Display',serif;font-size:clamp(32px,5vw,56px);font-weight:900;background:linear-gradient(135deg,#fff 0%,#f0c040 100%);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;margin-bottom:12px;line-height:1.1;}}
.sealed-sub{{font-size:clamp(15px,2vw,18px);color:var(--dim);line-height:1.7;max-width:480px;margin:0 auto 36px;font-weight:300;}}
.sealed-card{{background:rgba(240,192,64,.07);border:1px solid rgba(240,192,64,.25);border-radius:20px;padding:28px 32px;max-width:440px;margin:0 auto 32px;}}
.sealed-card-text{{font-size:15px;color:rgba(255,255,255,.8);line-height:1.7;}}
.btn-submit{{display:inline-block;background:linear-gradient(135deg,#4285f4,#0f9d58);border:none;border-radius:12px;padding:14px 32px;font-size:15px;font-weight:700;color:white;cursor:pointer;transition:all .2s;margin-bottom:10px;}}
.btn-submit:hover{{transform:translateY(-2px);box-shadow:0 6px 24px rgba(66,133,244,.3);}}
.sealed-note{{font-size:11px;color:var(--dimmer);display:block;margin-top:6px;}}
.setup-note{{margin-top:28px;background:rgba(240,192,64,.07);border:1px dashed rgba(240,192,64,.3);border-radius:16px;padding:20px 24px;}}
.setup-note-title{{font-size:12px;letter-spacing:2px;text-transform:uppercase;color:var(--gold);margin-bottom:12px;}}
.setup-note p{{font-size:13px;color:rgba(255,255,255,.65);line-height:1.7;margin-bottom:8px;}}
.setup-note code{{background:rgba(255,255,255,.1);border-radius:4px;padding:1px 6px;font-family:monospace;font-size:12px;color:var(--gold);}}
.setup-note a{{color:#4285f4;}}
.btn-retake{{display:block;width:100%;background:none;border:1px solid var(--cb);border-radius:12px;padding:14px;font-size:14px;font-weight:600;color:var(--dim);cursor:pointer;margin-top:14px;transition:all .2s;font-family:'Inter',sans-serif;}}
.btn-retake:hover{{border-color:rgba(255,255,255,.25);color:white;}}

@media(max-width:560px){{
  .options-grid{{grid-template-columns:1fr 1fr;}}
  .option-img-wrap,.option-img{{height:110px;}}
  .options-btn-grid{{grid-template-columns:1fr;}}
  .hero-img-wrap{{height:160px;}}
  .name-choice{{min-width:110px;}}
}}
</style>
</head>
<body>
<div class="container">

<!-- INTRO -->
<div class="screen active" id="screen-intro">
  <div class="intro-tag">✈ John's Epic 40th Birthday Trip</div>
  <h1 class="intro-title">Find Your<br>Perfect Adventure</h1>
  <p class="intro-sub">Answer honestly — we'll find the perfect destination. Results stay sealed until Jill reveals them!</p>
  <div class="name-section">
    <span class="name-section-label">Who's taking the quiz?</span>
    <div class="name-choices">
      <button class="name-choice" onclick="selectName('John')">
        <img src="data:image/jpeg;base64,{photos['JOHN']}" alt="John" class="name-photo"/>
        <span class="name-label-text">🎂 John</span>
      </button>
      <button class="name-choice" onclick="selectName('Jen')">
        <img src="data:image/jpeg;base64,{photos['JEN']}" alt="Jen" class="name-photo"/>
        <span class="name-label-text">✨ Jen</span>
      </button>
      <button class="name-choice" onclick="selectName('Jill')">
        <img src="data:image/jpeg;base64,{photos['JILL']}" alt="Jill" class="name-photo"/>
        <span class="name-label-text">✈️ Jill</span>
      </button>
      <button class="name-choice" onclick="selectName('Just Me Being Curious!')" style="min-width:200px;max-width:260px;">
        <img src="data:image/jpeg;base64,{photos['CURIOUS']}" alt="Curious" class="name-photo" style="aspect-ratio:4/3;object-position:center center;"/>
        <span class="name-label-text">🌍 Just Me Being Curious!</span>
      </button>
    </div>
  </div>
  <div class="dest-preview">
    <span class="dest-chip-i">🇪🇸 Ibiza</span><span class="dest-chip-i">🇵🇹 Portugal</span>
    <span class="dest-chip-i">🇲🇦 Morocco</span><span class="dest-chip-i">🇬🇭 Ghana</span>
    <span class="dest-chip-i">🇨🇦 Québec</span><span class="dest-chip-i">🇨🇦 Halifax</span>
    <span class="dest-chip-i">🇪🇸 Spain</span><span class="dest-chip-i">🇵🇪 Lima</span>
    <span class="dest-chip-i">🇨🇴 Cartagena</span>
  </div>
  <button class="btn-primary" id="startBtn" onclick="startQuiz()" disabled>Start the Quiz →</button>
</div>

<!-- QUESTION -->
<div class="screen" id="screen-question">
  <div class="pb-wrap"><div class="pb-fill" id="pbFill" style="width:0%"></div></div>
  <div class="q-meta">
    <div class="q-num" id="qNum">Question 1</div>
    <div class="q-rm">
      <div class="q-badge" id="qBadge">Pick One</div>
      <div class="q-cnt" id="qCnt">1 of 15</div>
    </div>
  </div>
  <div class="q-text" id="qText"></div>
  <div class="q-hint" id="qHint"></div>
  <div id="optCon"></div>
  <div class="nav-row">
    <button class="btn-back" id="btnBack" onclick="prevQ()">← Back</button>
    <button class="btn-next" id="btnNext" onclick="nextQ()">Next →</button>
  </div>
  <button class="btn-skip" id="btnSkip" onclick="skipQ()" style="display:none">None apply — skip this question →</button>
</div>

<!-- SEALED -->
<div class="screen" id="screen-sealed">
  <div class="sealed-screen">
    <span class="sealed-icon">🔮</span>
    <div class="sealed-title">Your Match<br>Is Sealed!</div>
    <p class="sealed-sub">Your perfect destination has been calculated and locked away. Jill has your result — she'll reveal it when the time is right. 🎉</p>
    <div class="sealed-card">
      <p class="sealed-card-text" id="sealedMsg">Thanks for taking the quiz!</p>
    </div>
    <button class="btn-submit" onclick="submitToForm()">📋 Send My Result to Jill →</button>
    <span class="sealed-note">Opens Google Form — takes 30 seconds</span>
    <div class="setup-note" id="setupNote">
      <div class="setup-note-title">📌 Setup — For Jill Only (delete before sharing)</div>
      <p><strong>Step 1:</strong> Create Google Form at <a href="https://forms.google.com" target="_blank">forms.google.com</a> with fields: <code>Name</code> · <code>Top Match</code> · <code>Score</code> · <code>Already Visited</code> · <code>Full Ranking</code>.</p>
      <p><strong>Step 2:</strong> Enable email notifications (Settings → Responses).</p>
      <p><strong>Step 3:</strong> Replace <code>GOOGLE_FORM_URL</code> in the script. Use placeholders <code>{{NAME}}</code> <code>{{TOP}}</code> <code>{{RANKING}}</code> <code>{{SCORE}}</code> <code>{{VISITED}}</code>.</p>
      <p><strong>Step 4:</strong> Delete this yellow box before sharing!</p>
    </div>
    <button class="btn-retake" onclick="retake()">↩ Retake the Quiz</button>
  </div>
</div>

</div>
<script>
const GOOGLE_FORM_URL="https://docs.google.com/forms/d/e/1FAIpQLSf-h86JPjkaQEEuCmbxaxz8yygYBqWAVoNA9VY7OsXxT4m4zQ/viewform?usp=pp_url&entry.2092323210={{NAME}}&entry.1140222774={{TOP}}&entry.1716741930={{SCORE}}&entry.2058184828={{VISITED}}&entry.919423870={{RANKING}}&entry.115984752={{ANSWERS}}";
const DESTINATIONS={{ibiza:{{name:"Ibiza, Spain",flag:"🇪🇸"}},portugal:{{name:"Portugal",flag:"🇵🇹"}},morocco:{{name:"Morocco",flag:"🇲🇦"}},ghana:{{name:"Ghana",flag:"🇬🇭"}},quebec:{{name:"Québec City",flag:"🇨🇦"}},halifax:{{name:"Halifax, Nova Scotia",flag:"🇨🇦"}},spain:{{name:"Barcelona / Spain",flag:"🇪🇸"}},lima:{{name:"Lima, Peru",flag:"🇵🇪"}},cartagena:{{name:"Cartagena, Colombia",flag:"🇨🇴"}}}};
const BTK={json.dumps(BEENTHERE_KEYS)};
const QS={json.dumps(QUESTIONS, ensure_ascii=False)};
const U=id=>`https://images.unsplash.com/photo-${{id}}?w=900&h=400&fit=crop&auto=format&q=80`;
const UC=id=>id.startsWith('data:')?id:`https://images.unsplash.com/photo-${{id}}?w=400&h=250&fit=crop&auto=format&q=80`;

let pName="",cur=0,ans=[];

function initAns(){{ans=QS.map(q=>q.type==="multi"?new Set():undefined);}}
function selectName(n){{pName=n;document.querySelectorAll(".name-choice").forEach(b=>b.classList.toggle("selected",b.textContent.includes(n)));document.getElementById("startBtn").disabled=false;}}
function startQuiz(){{if(!pName)return;initAns();cur=0;showScreen("screen-question");renderQ();}}

function renderQ(){{
  const q=QS[cur],tot=QS.length,sel=ans[cur];
  document.getElementById("qNum").textContent="Question "+(cur+1);
  document.getElementById("qCnt").textContent=(cur+1)+" of "+tot;
  document.getElementById("pbFill").style.width=(cur/tot*100)+"%";
  document.getElementById("qBadge").textContent=q.type==="multi"?"Pick All That Apply":"Pick One";
  document.getElementById("qText").textContent=q.text;
  const hint=document.getElementById("qHint");hint.textContent=q.hint||"";hint.style.display=q.hint?"block":"none";
  document.getElementById("btnBack").disabled=cur===0;
  document.getElementById("btnSkip").style.display=q.id==="beenthere"?"block":"none";
  const con=document.getElementById("optCon");con.innerHTML="";

  if(q.chipOnly){{
    const g=document.createElement("div");g.className="chips-grid";
    q.options.forEach((o,i)=>{{
      const c=document.createElement("button");c.className="chip-opt"+(sel.has(i)?" selected":"");
      c.innerHTML=`<span style="font-size:20px">${{o.emoji}}</span><span>${{o.label}}</span>`;
      c.onclick=()=>{{const s=ans[cur];s.has(i)?s.delete(i):s.add(i);renderQ();}};
      g.appendChild(c);
    }});
    con.appendChild(g);
  }} else if(q.heroImg||q.btnOnly){{
    // Hero image (if present) then button grid
    if(q.heroImg){{
      const hw=document.createElement("div");hw.className="hero-img-wrap";
      const hi=document.createElement("img");hi.className="hero-img";
      hi.src=U(q.heroImg);hi.alt="";hi.loading="lazy";
      hi.onerror=()=>{{hw.style.display="none";}};
      hw.appendChild(hi);con.appendChild(hw);
    }}
    const g=document.createElement("div");g.className="options-btn-grid";
    const isMulti=q.type==="multi";
    q.options.forEach((o,i)=>{{
      const isSelected=isMulti?sel.has(i):sel===i;
      const btn=document.createElement("button");btn.className="option-btn"+(isSelected?" selected":"");
      btn.innerHTML=`<span class="opt-btn-icon">${{o.emoji}}</span><span class="opt-btn-content"><span class="opt-btn-lbl">${{o.label}}</span><span class="opt-btn-sub">${{o.sub}}</span></span><div class="opt-btn-chk${{isMulti?" cb":""}}">${{isSelected?"✓":""}}</div>`;
      btn.onclick=()=>selOpt(i);
      g.appendChild(btn);
    }});
    con.appendChild(g);
  }} else {{
    // Photo cards
    const g=document.createElement("div");g.className="options-grid";
    const isMulti=q.type==="multi";
    q.options.forEach((o,i)=>{{
      const isSelected=isMulti?sel.has(i):sel===i;
      const card=document.createElement("button");card.className="option-card"+(isSelected?" selected":"");
      card.innerHTML=`<div class="option-img-wrap"><img class="option-img" src="${{UC(o.img)}}" alt="${{o.label}}" loading="lazy" onerror="this.parentElement.style.display='none'"/></div><div class="option-body"><div class="opt-top"><span class="opt-em">${{o.emoji}}</span><span class="opt-lbl">${{o.label}}</span><div class="opt-chk${{isMulti?" cb":""}}">${{isSelected?"✓":""}}</div></div><div class="opt-sub">${{o.sub}}</div></div>`;
      card.onclick=()=>selOpt(i);
      g.appendChild(card);
    }});
    con.appendChild(g);
  }}
  updNextBtn();
}}

function selOpt(i){{const q=QS[cur];if(q.type==="multi"){{const s=ans[cur];s.has(i)?s.delete(i):s.add(i);}}else ans[cur]=i;renderQ();}}
function updNextBtn(){{const q=QS[cur],sel=ans[cur],has=q.type==="multi"?sel.size>0:sel!==undefined;const btn=document.getElementById("btnNext");btn.textContent=cur===QS.length-1?"Seal My Result →":"Next →";btn.classList.toggle("visible",has||q.id==="beenthere");}}
function prevQ(){{if(cur>0){{cur--;renderQ();}}}}
function nextQ(){{const q=QS[cur],sel=ans[cur],has=q.type==="multi"?sel.size>0:sel!==undefined;if(!has&&q.id!=="beenthere")return;cur++;if(cur<QS.length)renderQ();else showSealed();}}
function skipQ(){{cur++;if(cur<QS.length)renderQ();else showSealed();}}

function calcScores(){{
  const sc={{}};Object.keys(DESTINATIONS).forEach(k=>sc[k]=0);
  QS.forEach((q,i)=>{{
    const sel=ans[i];if(sel===undefined||sel===null)return;
    if(q.type==="multi"){{if(!sel||sel.size===0)return;sel.forEach(idx=>Object.entries(q.options[idx].scores).forEach(([d,p])=>{{if(d in sc)sc[d]+=p;}}));}}
    else Object.entries(q.options[sel].scores).forEach(([d,p])=>{{if(d in sc)sc[d]+=p;}});
  }});
  const nqI=QS.findIndex(q=>q.id==="novelty"),btI=QS.findIndex(q=>q.id==="beenthere");
  const nv=ans[nqI],bt=ans[btI];
  if(bt&&bt.size>0){{const pen=nv===0?6:nv===1?3:nv===2?1:0;if(pen>0)bt.forEach(idx=>{{const k=BTK[idx];if(k&&k in sc)sc[k]-=pen;}});}}
  return sc;
}}

function showSealed(){{
  const sc=calcScores(),ranked=Object.keys(sc).sort((a,b)=>sc[b]-sc[a]);
  const btI=QS.findIndex(q=>q.id==="beenthere"),bt=ans[btI]||new Set();
  const visited=bt.size>0?Array.from(bt).map(i=>DESTINATIONS[BTK[i]]?.name).join(", "):"None";
  const ansLines=QS.map((q,i)=>{{const s=ans[i];if(q.id==="beenthere")return `${{q.text}}: ${{s&&s.size>0?Array.from(s).map(j=>q.options[j].label).join(", "):"None"}}`;if(q.type==="multi")return `${{q.text}}: ${{s&&s.size>0?Array.from(s).map(j=>q.options[j].label).join(", "):"(skipped)"}}`;return `${{q.text}}: ${{s!==undefined?q.options[s].label:"(skipped)"}}`;}}).join("\\n");
  window._qr={{name:pName,top:DESTINATIONS[ranked[0]].name,ranking:ranked.map((d,i)=>`${{i+1}}. ${{DESTINATIONS[d].name}} (${{sc[d]}} pts)`).join(" | "),score:sc[ranked[0]],visited,answers:ansLines}};
  document.getElementById("sealedMsg").textContent=`${{pName}}, your answers have been matched to a destination — and it's a great one. Your result is locked until Jill decides it's time to reveal. Click below to send it! 🔒`;
  showScreen("screen-sealed");window.scrollTo(0,0);
}}

function submitToForm(){{
  const r=window._qr;if(!r)return;
  if(!GOOGLE_FORM_URL){{const t=`Name: ${{r.name}}\\nTop Match: ${{r.top}}\\nScore: ${{r.score}}\\nAlready Visited: ${{r.visited}}\\nFull Ranking: ${{r.ranking}}`;if(navigator.clipboard)navigator.clipboard.writeText(t).then(()=>alert("📋 Copied!\\n\\n"+t));else alert(t);return;}}
  window.open(GOOGLE_FORM_URL.replace("{{NAME}}",encodeURIComponent(r.name)).replace("{{TOP}}",encodeURIComponent(r.top)).replace("{{RANKING}}",encodeURIComponent(r.ranking)).replace("{{SCORE}}",encodeURIComponent(r.score)).replace("{{VISITED}}",encodeURIComponent(r.visited)).replace("{{ANSWERS}}",encodeURIComponent(r.answers)),"_blank");
}}

function retake(){{initAns();cur=0;showScreen("screen-intro");window.scrollTo(0,0);}}
function showScreen(id){{document.querySelectorAll(".screen").forEach(s=>s.classList.remove("active"));document.getElementById(id).classList.add("active");}}
</script>
</body>
</html>'''

with open("/sessions/brave-wonderful-pascal/mnt/outputs/Johns_40th_Quiz.html","w") as f:
    f.write(html)
with open("/sessions/brave-wonderful-pascal/mnt/Desktop/Johns_40th_Quiz.html","w") as f:
    f.write(html)
print(f"Done. {len(html)//1024}KB")
